#include <stdio.h>

int main(void) {
    int x = 1, y = 2, z = 3;
    int *arr[3];            /* 指针数组：3 个 int* */
    arr[0] = &x; arr[1] = &y; arr[2] = &z;
    printf("arr[0..2] = %d %d %d\n", *arr[0], *arr[1], *arr[2]);
    printf("sizeof(arr) = %zu (3 个指针)\n", sizeof(arr));

    int m[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int (*par)[3] = m;      /* 数组指针：指向一行 */
    printf("par[1][2] = %d\n", par[1][2]);
    printf("(char*)(par+1)-(char*)par = %td (一整行字节数)\n",
           (char *)(par + 1) - (char *)par);
    return 0;
}
